<template><section class="call-billing-queue"><header><h3>Client calls awaiting billing review</h3><button @click="load" :disabled="loading">Refresh</button></header><p>Provider requests are review items, not charges. Review the service documentation, applicable code and payer rules before preparing a claim; attach its ID here afterward.</p><p v-if="error" role="alert">{{ error }}</p><p v-else-if="loading">Loading…</p><p v-else-if="!items.length">No client calls have been submitted for billing review.</p><article v-for="item in items" :key="item.callId"><strong>Client #{{ item.clientId }} · {{ item.direction }} call · {{ new Date(item.startedAt).toLocaleString() }}</strong><p>{{ item.details?.description }}</p><CallBillingReview :call-id="item.callId" /></article><p v-if="hasMore">Showing the latest 200 requests.</p></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import api from '../../services/api';import CallBillingReview from '../communications/CallBillingReview.vue';
const props=defineProps({agencyId:{type:[Number,String],required:true}}),items=ref([]),loading=ref(false),error=ref(''),hasMore=ref(false);let seq=0;
async function load(){const key=++seq;items.value=[];error.value='';loading.value=true;try{const {data}=await api.get('/communications/call-billing',{params:{agencyId:props.agencyId}});if(key===seq){items.value=data.items;hasMore.value=data.hasMore;}}catch{if(key===seq)error.value='Unable to load call billing reviews.';}finally{if(key===seq)loading.value=false;}}
watch(()=>props.agencyId,load,{immediate:true});onBeforeUnmount(()=>seq++);
</script>
<style scoped>.call-billing-queue{padding:22px;margin:20px 0;background:var(--bg-primary,#fff);border:1px solid #d3dfe8;border-radius:12px}header{display:flex;justify-content:space-between;align-items:center}article{padding:16px 0;border-top:1px solid #d3dfe8}p{line-height:1.5}</style>
